    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case WorkRequestQualifier_supervisorProcess_workRequestQualifier_id =>
          val prefix = "WorkRequestQualifier_supervisorProcess_workRequestQualifier_RM_TestSuite"
