            st"""package scp_candidate.Factory_Flow
                |
                |import org.sireum._
                |import scp_candidate.Factory_Flow._
                |
                |class ${suiteName} extends WorkRequestQualifier_supervisorProcess_workRequestQualifier_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
