  def genTestCase(observationKind: ObservationKind.Type, preContainer: Option[String], postContainer: Option[String], testNameSuffix: Option[String]): ST = {
    val tq = "\"\"\""
    val suffix: String =
      if (testNameSuffix.nonEmpty) testNameSuffix.get
      else ""

    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.FactoryFlowSupervisor_Instance_supervisorProcess_workRequestQualifier_postInit =>
        return (st"""// Begin test cases for FactoryFlowSupervisor_Instance_supervisorProcess_workRequestQualifier_postInit
                    |
                    |test(s"FactoryFlowSupervisor_Instance_supervisorProcess_workRequestQualifier_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val postContainer = scp_candidate.JSON.toFactory_FlowWorkRequestQualifier_supervisorProcess_workRequestQualifier_PostState_Container_PS(postJson).left
